arguments.argument:
with(sys_mouse)
{
    for(i=0; i!=vab_unit; i+=1)
    {
        if instance_number(vab_unit_id[i])
        {
            if global.player_control=vab_unit_id[i].player and vab_unit_id[i].moni_go=1
            {
                vab_unit_id[i].moni_go_waits=2
                vab_unit_id[i].moni_go_waits_id=other.id
                vab_unit_id[i].go_check=0
                /*on*/buffer_clear(fnv_sned)
                write_uint(fnv_sned, vab_unit_id[i].on)
                write_uint(fnv_sned, other.on)
                write_uint(fnv_sned, vab_unit_id[i].x)
                write_uint(fnv_sned, vab_unit_id[i].y)
                fn_message_send(global.socket, send_other, 27)
            }
        }
    }
}
